     1→/**
     2→ * Reference normalization and routing utilities.
     3→ *
     4→ * Provides consistent handling of @-prefixed references (tasks, specs, plans, sessions)
     5→ * across the web UI. Normalizes @ prefixes, detects reference types, and generates
     6→ * navigation URLs.
     7→ *
     8→ * AC: @ui-reference-display ac-1
     9→ */
    10→
    11→/** Types of entities that can be referenced in the UI. */
    12→export type RefType = 'task' | 'spec' | 'plan' | 'session';
    13→
    14→/**
    15→ * Strip the leading @ from a reference string if present.
    16→ * Prevents double @@ when displaying with @ prefix.
    17→ */
    18→export function normalizeRef(ref: string): string {
    19→	return ref.startsWith('@') ? ref.slice(1) : ref;
    20→}
    21→
    22→/**
    23→ * Get a short display version of a reference (first 8 chars of the normalized ref).
    24→ */
    25→export function shortRef(ref: string): string {
    26→	return normalizeRef(ref).slice(0, 8);
    27→}
    28→
    29→/**
    30→ * Build the navigation URL for a given reference type and ID.
    31→ * @param basePath - The SvelteKit base path (from $app/paths). Defaults to ''.
    32→ */
    33→export function refHref(type: RefType, ref: string, basePath = ''): string {
    34→	const encoded = encodeURIComponent(ref);
    35→	switch (type) {
    36→		case 'task':
    37→			return `${basePath}/tasks/board?ref=${encoded}`;
    38→		case 'spec':
    39→			return `${basePath}/specs?ref=${encoded}`;
    40→		case 'plan':
    41→			return `${basePath}/plans?ref=${encoded}`;
    42→		case 'session':
    43→			return `${basePath}/sessions/${normalizeRef(ref)}`;
    44→	}
    45→}
    46→
